const { window } = dom;
const { document } = window;

window.requestAnimationFrame = window.requestAnimationFrame || function(cb){ return setTimeout(()=>cb(Date.now()),0); };

let pass = 0, fail = 0;
const check = (n, c) => { c ? pass++ : (fail++, console.error('FAIL:', n)); };

// jsdom: no PointerEvent; use generic Event with coords
function PE(type, o){ const e = new window.Event(type, { bubbles: true, cancelable: true }); Object.assign(e, o); return e; }

document.querySelector('[data-open-test]').click();
const list = document.querySelector('.disc-list');
const items = () => [...list.children];
const order = () => items().map(li => li.dataset.type + ':' + li.querySelector('.disc-text').textContent);

const before = order();

// drag last item to the top
