li.dispatchEvent(PE('pointerdown', { clientX: 100, clientY: 100, button: 0, isPrimary: true, target: li }));
li.dispatchEvent(PE('pointermove', { clientX: 100, clientY: 60,  isPrimary: true, target: li })); // not yet beyond threshold? dx=0,dy=40 => lifted
li.dispatchEvent(PE('pointermove', { clientX: 100, clientY: -1,  isPrimary: true, target: li })); // y=-1 < 0 => before first
li.dispatchEvent(PE('pointerup',   { clientX: 100, clientY: -1,  isPrimary: true, target: li }));

const after = order();
check('drag lifted & reordered (last->first)', JSON.stringify(after) !== JSON.stringify(before) && after[0] === before[3] && after[3] === before[0]);
check('ghost removed from body', document.querySelectorAll('.disc-item--lift').length === 0);
check('no is-slot left', document.querySelectorAll('.is-slot').length === 0);
check('ranks updated to 1..4', items().map((li,i)=>li.querySelector('.disc-rank').textContent === String(i+1)).every(Boolean));
check('body not stuck is-dragging', !document.body.classList.contains('is-dragging'));

// drag item 0 to bottom (y large positive -> all midpoints above -> append)
const li2 = items()[0];
li2.dispatchEvent(PE('pointerdown', { clientX: 50, clientY: 10,  button: 0, isPrimary: true, target: li2 }));
li2.dispatchEvent(PE('pointermove', { clientX: 50, clientY: 60,  isPrimary: true, target: li2 }));
li2.dispatchEvent(PE('pointermove', { clientX: 50, clientY: 5000, isPrimary: true, target: li2 }));
li2.dispatchEvent(PE('pointerup',   { clientX: 50, clientY: 5000, isPrimary: true, target: li2 }));
