const exp={d:0,i:0,s:0,c:0};
orig.forEach(l=>{ const t=l.map(x=>x[0]); exp[t[0]]++; exp[t[3]]--; });
for(let k=0;k<7;k++) document.getElementById('btnNext').click();
document.getElementById('btnFinish').click();
