from html.parser import HTMLParser
VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]; self.errors=[]
    def handle_starttag(self,tag,attrs):
        if tag not in VOID: self.stack.append((tag,self.getpos()))
    def handle_endtag(self,tag):
        if not self.stack: self.errors.append(f'unmatched close </{tag}> at {self.getpos()}'); return
        t,pos=self.stack.pop()
        if t!=tag: self.errors.append(f'mismatch: <{t}> opened at {pos}, closed by </{tag}> at {self.getpos()}')
p=P()
p.feed(open('index.html',encoding='utf-8').read())
if p.stack: p.errors.append(f'unclosed: {p.stack}')
print('ERRORS:' if p.errors else 'HTML well-formed')
for e in p.errors: print(' ', e)
