const path = require('path');
const puppeteer = require('puppeteer-core');

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome-stable',
    headless: true,
    args: ['--no-sandbox', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('requestfailed', r => errors.push('requestfailed: ' + r.url()));
  const failedExternal = [];
  page.on('request', r => { const u = r.url(); if (/^https?:/i.test(u)) failedExternal.push(u); });

  const url = 'file://' + path.resolve(__dirname, '..', 'index.html');
  await page.goto(url, { waitUntil: 'networkidle0' });

  let pass = 0, fail = 0;
  const check = async (n, c) => { const v = await c; v ? pass++ : (fail++, console.error('FAIL:', n)); };

  await check('96 items rendered', page.evaluate(() => document.querySelectorAll('.disc-item').length === 96));
  await check('8 tabs', page.evaluate(() => document.querySelectorAll('.tab').length === 8));

  await page.click('[data-open-test]');
  await new Promise(r => setTimeout(r, 250));
  await check('modal visible', page.evaluate(() => !document.getElementById('discModal').hidden && document.getElementById('discModal').classList.contains('is-shown')));

