    const b = el => { const r = el.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; };
    return { before: lis.map(li => li.dataset.type), src: b(lis[2]), dst: { x: b(lis[0]).x, y: b(lis[0]).y - b(lis[0]).y * 0.4 } };
  });

  await page.mouse.move(info.src.x, info.src.y);
  await page.mouse.down();
  // stepwise moves with intermediate points (pointermove path)
  const steps = 8;
  for (let i = 1; i <= steps; i++) {
    const x = info.src.x + (info.dst.x - info.src.x) * i / steps;
    const y = info.src.y + (info.dst.y - info.src.y) * i / steps;
    await page.mouse.move(x, y, { steps: 2 });
    await new Promise(r => setTimeout(r, 25));
  }
  await page.mouse.up();
  await new Promise(r => setTimeout(r, 80));

  const afterDrag = await page.evaluate(() => [...document.querySelector('.disc-list').children].map(li => li.dataset.type));
