  for (let i = 0; i < 7; i++) { await page.click('#btnNext'); await new Promise(r => setTimeout(r, 30)); }
  await page.click('#btnFinish');
  await new Promise(r => setTimeout(r, 150));

  await check('result shown', page.evaluate(() => document.getElementById('discResult').classList.contains('is-active')));

