  await page.keyboard.press('Escape');
  await new Promise(r => setTimeout(r, 350));
  await check('Esc closes modal', page.evaluate(() => document.getElementById('discModal').hidden));

  // reopen -> fresh test
  await page.click('[data-open-test]');
  await new Promise(r => setTimeout(r, 200));
  await check('reopen: 96 items, modal fresh', page.evaluate(() => !document.getElementById('discModal').hidden && document.querySelectorAll('.disc-item').length === 96));

