  if (errors.length) { console.log('BROWSER ERRORS:'); errors.forEach(e => console.log('  ', e)); }
  if (failedExternal.length) { console.log('EXTERNAL REQUESTS:'); failedExternal.forEach(u => console.log('  ', u)); }
  console.log(errors.length === 0 && failedExternal.length === 0 ? 'no console errors, no external requests' : 'SEE ERRORS ABOVE');
  await browser.close();
  process.exit(fail ? 1 : 0);
})().catch(e => { console.error('E2E FATAL', e); process.exit(2); });
