const fs=require('fs'),path=require('path');
const { JSDOM } = require('jsdom');
const html = fs.readFileSync(path.join(__dirname,'..','index.html'),'utf8');
const dom = new JSDOM(html,{runScripts:'dangerously',pretendToBeVisual:true,url:'file:///index.html'});
const { window }=dom; const { document }=window;
let pass=0,fail=0; const check=(n,c)=>{c?pass++:(fail++,console.error('FAIL:',n));};

document.querySelector('[data-open-test]').click();
const list = document.querySelector('.disc-list');
const ord = () => [...list.children].map(li=>li.dataset.type);

// keyboard: move item idx1 to top via ArrowUp twice
const o0 = ord();
list.children[1].dispatchEvent(new window.KeyboardEvent('keydown',{key:'ArrowUp',bubbles:true,cancelable:true}));
check('ArrowUp moves up', JSON.stringify(ord()) === JSON.stringify([o0[1],o0[0],o0[2],o0[3]]));
list.children[0].dispatchEvent(new window.KeyboardEvent('keydown',{key:'ArrowDown',bubbles:true,cancelable:true}));
check('ArrowDown moves down', JSON.stringify(ord()) === JSON.stringify([o0[0],o0[1],o0[2],o0[3]]));
// Home/End
list.children[2].dispatchEvent(new window.KeyboardEvent('keydown',{key:'End',bubbles:true,cancelable:true}));
check('End moves to bottom', ord()[3] === o0[2]);
list.children[3].dispatchEvent(new window.KeyboardEvent('keydown',{key:'Home',bubbles:true,cancelable:true}));
check('Home moves to top', ord()[0] === o0[2]);
// restore
const back = [o0[2],o0[0],o0[1],o0[3]];
list.children[0].dispatchEvent(new window.KeyboardEvent('keydown',{key:'End',bubbles:true,cancelable:true}));
check('restored', JSON.stringify(ord()) === JSON.stringify([o0[0],o0[1],o0[3],o0[2]]));
check('ranks ok', [...list.children].every((li,i)=>li.querySelector('.disc-rank').textContent===String(i+1)));

// default (no reorder) score vs original algorithm
const orig = require('../disc_data.json');
// re-scored: list1 was reordered by keyboard test (minor became d): adjust expectation
const exp={d:0,i:0,s:0,c:0};
const finalFirst = ord(); // current state of list1
exp[finalFirst[0]] += 1; exp[finalFirst[3]] -= 1;
for (let n = 1; n < orig.length; n++) {
  const t = orig[n].map(x=>x[0]); exp[t[0]]++; exp[t[3]]--;
}
for(let k=0;k<7;k++) document.getElementById('btnNext').click();
document.getElementById('btnFinish').click();
const want=`D:${exp.d}, I:${exp.i}, S:${exp.s}, C:${exp.c}`;
const got=document.getElementById('scoreFlat').textContent;
check('score matches algorithm incl. keyboard reorders: '+got+' expected '+want, got===want);
window.setTimeout(() => {
  const wb = [...document.querySelectorAll('#scoreCells .cell')].map(c => c.querySelector('i b').style.width);
  check('bars valid: all parsable ' + wb.join('/') + ', some >0', wb.every(w => !isNaN(parseFloat(w))) && wb.some(w => parseFloat(w) > 0));
  console.log(pass + ' passed, ' + fail + ' failed');
  process.exit(fail ? 1 : 0);
}, 120);
process.on('unhandledRejection', e => { console.error(e); process.exit(2); });

