  // reorder item idx2 to top with mouse drag (mouse works on firefox too)
  const info = await page.evaluate(() => {
    const ul = document.querySelector('.disc-list');
    const lis = [...ul.children];
    const b = el => { const r = el.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; };
    const src = b(lis[2]);
    const dst = { x: b(lis[0]).x, y: lis[0].getBoundingClientRect().top + 3 };
    return { before: lis.map(li => li.dataset.type), src, dst };
  });
  await page.mouse.move(info.src.x, info.src.y);
  await page.mouse.down();
  for (let i = 1; i <= 10; i++) {
    const x = info.src.x + (info.dst.x - info.src.x) * i / 10;
    const y = info.src.y + (info.dst.y - info.src.y) * i / 10;
    await page.mouse.move(x, y, { steps: 2 });
    await new Promise(r => setTimeout(r, 20));
  }
  await page.mouse.up();
  await new Promise(r => setTimeout(r, 120));
  const after = await page.evaluate(() => [...document.querySelector('.disc-list').children].map(li => li.dataset.type));
  console.log('drag reorder [i,c,d,s] ->', after.join(), '(expect first=d)');

  // complete
  for (let i = 0; i < 7; i++) { await page.click('#btnNext'); }
  await page.click('#btnFinish');
  await new Promise(r => setTimeout(r, 400));
  const res = await page.evaluate(() => ({
    shown: document.getElementById('discResult').classList.contains('is-active'),
    flat: document.getElementById('scoreFlat').textContent,
    cells: [...document.querySelectorAll('#scoreCells .cell b')].map(b => b.textContent)
  }));
  console.log('result:', JSON.stringify(res));
  const expectFlat = 'D:0, I:-1, S:-3, C:4';
  const ok = modalOk && after[0] === 'd' && res.shown && res.flat === expectFlat;
  console.log(ok ? 'FIREFOX SMOKE: PASS' : 'FIREFOX SMOKE: FAIL');
  if (errs.length) console.log(errs);
  if (requests.length) console.log('requests:', requests);
  await browser.close();
  process.exit(ok ? 0 : 1);
})().catch(e => { console.error('FATAL', e); process.exit(2); });
